// Discursivas: f = fonte, t = tema, q = pergunta, r = resposta-modelo (HTML), k = pontos-chave
const DISCURSIVAS = [
  // ---------- Atividade de Revisão ----------
  { f: "Atividade de Revisão – Q5", t: "s1", q: "Explique a diferença entre tempo de resposta e vazão (throughput). Um sistema pode apresentar boa vazão e, ao mesmo tempo, ter um tempo de resposta elevado? Explique.",
    r: "<p><b>Tempo de resposta</b> é o intervalo entre o envio de uma requisição e o recebimento da resposta (visão do usuário). <b>Vazão</b> é a quantidade de requisições concluídas por unidade de tempo (visão da capacidade do sistema).</p><p><b>Sim.</b> Perto da saturação, o sistema pode estar concluindo muitas requisições por segundo (vazão alta, no teto), mas cada requisição passa muito tempo esperando na fila. Como R = espera + serviço, a fila faz R crescer mesmo com vazão alta. Ex.: sistema de matrículas no pico atende 55 req/s, mas com 2,8 s de resposta.</p>",
    k: ["Define tempo de resposta (por requisição)", "Define vazão (por unidade de tempo)", "Responde SIM", "Explica a fila / saturação (R = espera + serviço)"] },
  { f: "Atividade de Revisão – Q6", t: "s2", q: "Um servidor apresenta utilização média de CPU de 95%. Isso significa necessariamente que o sistema está com baixo desempenho? Justifique.",
    r: "<p><b>Não necessariamente.</b> Utilização alta indica que o recurso está bem aproveitado, mas desempenho é medido pelo que o usuário percebe (tempo de resposta, vazão, erros). Se os requisitos estão sendo atendidos, 95% pode ser aceitável (ex.: processamento em lote).</p><p>Porém, é um <b>alerta</b>: perto da saturação sobra pouca folga para picos, e o tempo de resposta cresce de forma não linear (M/M/1: a 95% R = 20× o tempo de serviço). É preciso verificar fila de processos, tempo de resposta e taxa de erros antes de concluir.</p>",
    k: ["Responde NÃO necessariamente", "Utilização ≠ desempenho percebido", "Verificar tempo de resposta/fila/erros", "Alerta: pouca folga, R cresce perto da saturação"] },
  { f: "Atividade de Revisão – Q7", t: "s3", q: "Explique a diferença entre memória RAM e armazenamento secundário. Por que a substituição de um HDD por um SSD pode melhorar o desempenho de determinadas aplicações?",
    r: "<p><b>RAM</b> é memória principal, volátil e rápida: guarda os programas e dados em uso. <b>Armazenamento secundário</b> (HDD/SSD) é persistente, maior e muito mais lento que a RAM.</p><p>O HDD tem partes mecânicas: o tempo de acesso = busca (seek) + latência rotacional + transferência. O SSD usa memória flash, sem partes móveis, então tem latência muito menor e muito mais IOPS — principalmente em <b>acessos aleatórios</b> (bancos de dados, muitos arquivos pequenos). Por isso aplicações <b>I/O-bound</b> melhoram muito (caso Alfa x Beta: 38,2 s → 1,9 s). Aplicações CPU-bound podem ganhar pouco.</p>",
    k: ["RAM volátil e rápida; secundário persistente e lento", "HDD mecânico: seek + rotação", "SSD sem partes móveis → menor latência/mais IOPS", "Maior ganho em acesso aleatório / I/O-bound"] },
  { f: "Atividade de Revisão – Q8", t: "s4", q: "Numa videoconferência, os usuários relatam áudio e vídeo com interrupções. Explique a diferença entre latência, jitter e perda de pacotes. Qual deles está relacionado à variação do atraso na entrega dos pacotes?",
    r: "<p><b>Latência</b>: tempo que um pacote leva da origem ao destino (propagação + transmissão + processamento + fila). <b>Jitter</b>: <b>variação</b> desse atraso entre pacotes consecutivos. <b>Perda</b>: pacotes que não chegam (falha física ou descarte por fila cheia).</p><p>O indicador ligado à variação do atraso é o <b>jitter</b>. Jitter alto esvazia o buffer de jitter, gerando cortes e travamentos; pacotes que chegam tarde demais são descartados. Referências: jitter &lt; 20 ms excelente; 20–30 ms aceitável.</p>",
    k: ["Define latência", "Define jitter como variação do atraso", "Define perda e suas causas", "Resposta: JITTER"] },
  { f: "Atividade de Revisão – Q9", t: "s4", q: "Qual é a principal diferença entre TCP e UDP em relação à entrega dos dados? Por que uma aplicação de videoconferência pode utilizar UDP?",
    r: "<p><b>TCP</b> oferece entrega confiável e ordenada: confirma recebimento e <b>retransmite</b> o que se perdeu. <b>UDP</b> envia datagramas <b>sem garantia</b> de entrega, ordem ou retransmissão.</p><p>Na videoconferência, um pacote que chega atrasado perde a utilidade (a fala já passou). Esperar retransmissão do TCP aumentaria atraso e jitter. Com UDP, perde-se pontualmente um pedaço (que o app pode compensar) mas mantém-se o tempo real. (O QUIC, usado hoje, também roda sobre UDP.)</p>",
    k: ["TCP confiável com retransmissão", "UDP sem garantia/retransmissão", "Pacote atrasado é inútil em tempo real", "Retransmissão aumenta atraso"] },
  { f: "Atividade de Revisão – Q10", t: "s5", q: "Uma equipe compara dois servidores, mas executa os testes com quantidades diferentes de usuários e cargas de trabalho. Por que essa comparação pode levar a uma conclusão equivocada? O que deveria ser mantido igual?",
    r: "<p>Porque viola o princípio <b>ceteris paribus</b> (mantidas as demais condições constantes). A diferença de resultado pode ter sido causada pela <b>diferença no teste</b> e não pela tecnologia.</p><p>Deveriam ser mantidos iguais: a <b>carga de trabalho</b> (nº de usuários, perfil de requisições), os <b>dados</b> utilizados (mesma base), as <b>operações</b> executadas, as regras da aplicação e as <b>condições de rede</b>. Além disso, repetir os testes várias vezes.</p>",
    k: ["Cita ceteris paribus", "Diferença pode vir do teste, não da tecnologia", "Mesma carga/usuários e mesmos dados", "Mesmas operações e rede; repetir"] },
  { f: "Atividade de Revisão – Q11", t: "s5", q: "Um sistema apresenta disponibilidade de 99,8%. Explique o que esse percentual representa e por que disponibilidade e desempenho são indicadores diferentes.",
    r: "<p>99,8% significa que o serviço fica funcionando e acessível 99,8% do tempo; os 0,2% restantes são indisponibilidade ≈ <b>17,5 horas por ano</b> (0,002 × 8.760 h).</p><p><b>Disponibilidade</b> mede se o sistema <b>está no ar</b>; <b>desempenho</b> mede <b>quão bem</b> ele atende quando está no ar (tempo de resposta, vazão). Um sistema pode estar 100% disponível e muito lento, ou ser rapidíssimo mas cair com frequência.</p>",
    k: ["99,8% do tempo funcionando", "≈17,5 h/ano de indisponibilidade", "Disponibilidade = estar no ar", "Desempenho = qualidade do atendimento (R, X)"] },
  { f: "Atividade de Revisão – Q12", t: "s5", q: "Explique a diferença entre escalabilidade vertical e horizontal. Apresente um exemplo de cada uma.",
    r: "<p><b>Vertical (scale-up)</b>: aumentar os recursos de <b>uma mesma máquina</b>. Ex.: trocar o processador por um mais potente ou passar de 16 GB para 64 GB de RAM no servidor do banco. Limite físico e equipamentos caros.</p><p><b>Horizontal (scale-out)</b>: <b>acrescentar máquinas/instâncias</b> que trabalham em conjunto. Ex.: passar de 2 para 6 servidores web atrás de um balanceador de carga, ou autoscaling na nuvem. Atenção: não resolve gargalo em recurso compartilhado (ex.: banco único).</p>",
    k: ["Vertical = mais recursos na mesma máquina", "Exemplo vertical", "Horizontal = mais máquinas/instâncias", "Exemplo horizontal"] },

  // ---------- Atividade Semana 6 (Sistema de matrículas) ----------
  { f: "Atividade Semana 6 – 1a", t: "s6", q: "Qual é o principal problema observado durante o período de pico?",
    r: "<p>O sistema <b>não consegue atender toda a demanda</b>: chegam 80 req/s mas só 55 são atendidas. Isso gera fila (2 → 120 requisições aguardando) e <b>tempo de resposta 7× maior</b> (0,4 s → 2,8 s) — a lentidão relatada pelos alunos.</p>",
    k: ["Chegada (80) > atendimento (55)", "Fila cresce (2 → 120)", "Tempo de resposta 0,4 → 2,8 s"] },
  { f: "Atividade Semana 6 – 1b", t: "s6", q: "Compare a quantidade de requisições recebidas com a quantidade atendida. O que essa diferença pode indicar?",
    r: "<p>No normal, recebidas = atendidas (20 = 20): equilíbrio. No pico, 80 recebidas × 55 atendidas: <b>25 req/s sobram a cada segundo</b>. Indica que o sistema atingiu o <b>ponto de saturação</b> — a vazão parou de acompanhar a carga — e há um <b>gargalo</b> limitando a capacidade em ~55 req/s. O excedente se acumula em fila.</p>",
    k: ["Normal equilibrado; pico desequilibrado", "≈25 req/s excedentes", "Ponto de saturação / capacidade máx. ≈55", "Indica gargalo"] },
  { f: "Atividade Semana 6 – 1c", t: "s6", q: "Qual recurso apresenta o maior aumento de utilização? Que relação ele pode ter com a lentidão observada?",
    r: "<p>O <b>armazenamento</b>: 25% → 92% (+67 p.p.), maior que CPU (+43 p.p.) e RAM (+7 p.p.).</p><p>Como as consultas ao banco ficaram mais lentas no pico, uma hipótese é que o BD esteja fazendo muita E/S em disco (ex.: consultas sem índice adequado, varreduras, cache insuficiente). O disco saturado gera fila de E/S, as consultas demoram, as conexões ficam presas e as requisições se acumulam. É uma <b>hipótese</b> a ser verificada (latência por operação, fila do disco, planos de execução).</p>",
    k: ["Armazenamento 25% → 92%", "Relação com consultas lentas ao BD", "Fila de E/S → requisições presas", "Tratar como hipótese a verificar"] },
  { f: "Atividade Semana 6 – 1d", t: "s6", q: "A utilização da CPU, isoladamente, permite afirmar que o processador é o gargalo do sistema? Justifique.",
    r: "<p><b>Não.</b> 78% é alto, mas ainda há folga, e uma métrica isolada não prova a causa. O armazenamento a 92% e as consultas lentas são evidências mais fortes. Além disso, parte do uso de CPU pode ser consequência de outras esperas. Seria preciso ver a fila de processos de CPU, a utilização por núcleo (uma thread pode saturar um núcleo) e decompor o tempo de resposta para saber onde ele é gasto.</p>",
    k: ["Responde NÃO", "Métrica isolada não prova causa", "Armazenamento 92% é suspeito mais forte", "Verificar fila de CPU, por núcleo, decompor R"] },
  { f: "Atividade Semana 6 – 2a", t: "s6", q: "Explique o que representa a fila de 120 requisições aguardando atendimento.",
    r: "<p>São requisições que já chegaram mas <b>ainda não começaram a ser atendidas</b> porque o recurso gargalo está ocupado. Cada uma vai esperar todas as da frente; esse tempo de espera é somado ao tempo de serviço e forma o tempo de resposta. É a evidência direta de que a chegada superou a capacidade.</p>",
    k: ["Requisições esperando vez", "Recurso ocupado / capacidade excedida", "Espera soma no tempo de resposta"] },
  { f: "Atividade Semana 6 – 2b", t: "s6", q: "Qual é a relação entre o aumento da fila e o tempo de resposta?",
    r: "<p>R = <b>espera na fila + tempo de serviço</b>. Quanto maior a fila, maior a espera e maior o tempo de resposta. Pela <b>Lei de Little</b> (N = X × R), com X ≈ 55 req/s e R = 2,8 s, há ≈ 154 requisições no sistema — compatível com 120 na fila + as em atendimento. Perto da saturação, a relação não é linear: pequenos aumentos de carga fazem R explodir.</p>",
    k: ["R = espera + serviço", "Fila maior → espera maior", "Lei de Little N = X × R (≈154)", "Crescimento não linear perto da saturação"] },
  { f: "Atividade Semana 6 – 2c", t: "s6", q: "Se o sistema recebe mais requisições do que consegue atender, quais consequências podem ocorrer?",
    r: "<ul><li>Fila crescendo continuamente (≈ +25 req/s);</li><li>Tempo de resposta cada vez maior;</li><li><b>Timeouts</b> e aumento da <b>taxa de erros</b>;</li><li>Esgotamento de recursos (threads, conexões com o BD, memória), instabilidade e até queda do sistema;</li><li>Usuários repetindo requisições (F5), piorando a carga; matrículas não concluídas.</li></ul>",
    k: ["Fila e tempo de resposta crescentes", "Timeouts / taxa de erros", "Esgotamento de recursos / queda", "Impacto no usuário"] },
  { f: "Atividade Semana 6 – 3a", t: "s6", q: "Qual seria a vantagem de utilizar um modelo analítico para estudar esse problema?",
    r: "<p>Permite fazer <b>estimativas rápidas e baratas</b>, sem mexer no sistema real, e entender a relação entre carga, capacidade, utilização e espera. Ex.: com a Lei da Utilização (U = X × S) e a Lei de Little, estimar a partir de quantas req/s o armazenamento satura e qual capacidade seria necessária para 80 req/s. Limitação: depende de hipóteses simplificadoras.</p>",
    k: ["Rápido e barato", "Não precisa mexer no sistema real", "Relaciona carga, utilização e espera (U = X×S, Little)", "Limite: hipóteses simplificadoras"] },
  { f: "Atividade Semana 6 – 3b", t: "s6", q: "Em que situação seria mais adequado utilizar uma simulação?",
    r: "<p>Quando o sistema é <b>complexo demais</b> para um modelo matemático simples (várias camadas web → aplicação → BD → disco, picos variáveis, limites de conexões, prioridades) ou quando se quer <b>testar cenários</b> difíceis/caros de testar no ambiente real — ex.: simular o pico de matrícula com 120 req/s, comparar \"SSD novo\" × \"otimizar consultas\" × \"mais servidores\" antes de comprar.</p>",
    k: ["Sistema complexo para modelo simples", "Testar cenários sem risco/custo real", "Comparar alternativas antes de investir"] },
  { f: "Atividade Semana 6 – 3c", t: "s6", q: "Cite duas informações adicionais que deveriam ser coletadas para construir um modelo mais próximo do funcionamento real do sistema.",
    r: "<ul><li><b>Tempo de serviço (demanda) por requisição em cada componente</b>: web, aplicação, BD, disco;</li><li><b>Padrão de chegada</b> ao longo do tempo (picos, distribuição, horários);</li><li>Latência por operação e fila do disco; tempo das consultas mais lentas e seus planos de execução;</li><li>Limites de concorrência (pool de conexões, threads) e taxa de erros/timeouts.</li></ul>",
    k: ["Tempo de serviço por componente", "Padrão de chegada", "(Extra) latência/fila do disco, consultas, limites de conexões"] },
  { f: "Atividade Semana 6 – 3d", t: "s6", q: "Por que seria importante repetir os testes em diferentes condições de carga?",
    r: "<p>Porque os resultados <b>variam entre execuções</b> e uma única medição pode ser atípica. Variando a carga (20, 40, 60, 80 req/s...) é possível encontrar o <b>ponto de saturação</b>, ver como o tempo de resposta cresce (não linear) e identificar qual recurso satura primeiro. Repetições permitem calcular média, variabilidade e intervalos de confiança, dando conclusões confiáveis.</p>",
    k: ["Resultados variam; 1 execução pode enganar", "Encontrar ponto de saturação", "Ver qual recurso satura primeiro", "Média, variabilidade, IC"] },
  { f: "Atividade Semana 6 – 4", t: "s6", q: "Descreva duas ações que você adotaria para investigar a causa da lentidão antes de recomendar a compra de novos equipamentos.",
    r: "<ol><li><b>Analisar as consultas ao banco</b>: identificar as mais lentas no pico, ver os planos de execução (varreduras completas em tabelas grandes, índices faltando ou de baixa seletividade, locks).</li><li><b>Medir o armazenamento diretamente</b>: latência por operação, profundidade da fila de E/S e IOPS no pico (não confiar só no I/O Wait).</li><li>(Extra) Decompor o tempo de resposta por camada (fila, aplicação, BD) e fazer um teste de carga controlado aumentando gradualmente as req/s.</li></ol><p>Seguir o método: sintoma → evidência → hipótese → <b>verificação</b>.</p>",
    k: ["Investigar consultas/planos de execução do BD", "Medir disco: latência, fila, IOPS", "Decompor tempo de resposta / teste de carga", "Evitar compra sem evidência"] },
  { f: "Atividade Semana 6 – 13 (Análise final)", t: "s6", q: "Qual deve ser a primeira preocupação da equipe de TI: aumentar a capacidade dos servidores, investigar o armazenamento ou analisar as consultas ao banco de dados? Justifique com os dados. Se faltarem informações, quais seriam necessárias?",
    r: "<p><b>Investigar o armazenamento junto com as consultas ao banco</b> — os dois estão ligados. Dados: o armazenamento teve o maior salto (25% → 92%), as consultas ficaram mais lentas no pico, a CPU (78%) ainda tem folga e a RAM quase não mudou (45% → 52%). Comprar servidores sem saber a causa pode não resolver (o gargalo pode ser o BD/disco compartilhado) e gastar dinheiro à toa.</p><p>Talvez consultas ineficientes estejam gerando E/S excessiva; otimizá-las (índices, ajustes) pode resolver sem comprar nada. Dados ainda necessários: latência e fila do disco, planos de execução e tempos das consultas, decomposição do tempo de resposta por camada, configuração de memória do SGBD, testes repetidos com cargas diferentes.</p>",
    k: ["Escolhe investigar armazenamento/BD primeiro", "Usa os dados: 92%, consultas lentas, CPU com folga, RAM estável", "Comprar sem evidência pode não resolver", "Lista dados faltantes"] },

  // ---------- Semana 2 – perguntas de revisão ----------
  { f: "Semana 2 – Revisão 1", t: "s2", q: "Explique a diferença entre um sintoma relatado pelo usuário e uma evidência coletada por ferramentas de monitoramento. Por que agir diretamente sobre o sintoma pode levar a diagnósticos incorretos?",
    r: "<p><b>Sintoma</b> é a manifestação externa e subjetiva percebida pelo usuário (\"o pagamento demora 30 s\"). <b>Evidência</b> é um dado técnico, quantitativo e verificável coletado por ferramentas (\"tempo de resposta 28,4 s; I/O Wait 62%; consultas 4,2 s\").</p><p>O sintoma indica <b>que</b> há problema, mas nunca revela a <b>causa raiz</b>. Agir sobre ele leva a soluções precipitadas (ex.: comprar CPU quando 24 dos 25 s eram espera no banco).</p>",
    k: ["Sintoma = percepção externa", "Evidência = dado mensurável", "Sintoma não revela causa raiz", "Exemplo de ação precipitada"] },
  { f: "Semana 2 – Revisão 2", t: "s2", q: "Um analista vê I/O Wait de 65% e conclui que o disco está com defeito ou saturado. Por que essa conclusão pode ser precipitada e quais métricas examinar?",
    r: "<p>I/O Wait é uma <b>subclasse do tempo ocioso</b> da CPU: indica que a CPU não tinha trabalho e havia E/S pendente. Não mede o uso do disco. Com pouca carga de CPU e uma thread lendo o disco, o I/O Wait pode ser alto com o disco perfeitamente normal.</p><p>Examinar métricas diretas do disco: <b>tempo de atendimento/latência por operação</b>, <b>profundidade da fila de E/S</b>, utilização do dispositivo e IOPS.</p>",
    k: ["I/O Wait = CPU ociosa com E/S pendente", "Não mede ocupação do disco", "Latência por operação", "Fila de E/S / utilização do dispositivo"] },
  { f: "Semana 2 – Revisão 3", t: "s2", q: "É correto afirmar que um recurso só é gargalo se estiver a 100% de utilização? Justifique com exemplos.",
    r: "<p><b>Não.</b> Gargalo é o componente que restringe o fluxo global, independentemente de chegar a 100%. Exemplos: disco com tempos degradados a 60–70% por latência de busca aleatória e filas internas; servidor de 4 núcleos com média de 25% mas um núcleo saturado por uma thread crítica; <b>locks</b> no banco travando transações com CPU e RAM baixas; limites de concorrência (pool de conexões) gerando fila.</p>",
    k: ["Responde NÃO", "Disco degradado a 60–70%", "Um núcleo saturado (média 25%)", "Locks / limites de concorrência"] },
  { f: "Semana 2 – Revisão 4", t: "s2", q: "Sob quais circunstâncias o otimizador escolhe um Full Table Scan mesmo com estrutura adequada?",
    r: "<p>Quando a <b>tabela é pequena</b> (ler blocos contíguos é mais rápido que consultar o índice) ou quando a consulta <b>seleciona uma fração grande das linhas</b> (muitos acessos aleatórios via índice seriam mais lentos que uma leitura sequencial).</p>",
    k: ["Tabela pequena", "Consulta retorna grande fração das linhas", "Leitura sequencial mais eficiente"] },
  { f: "Semana 2 – Revisão 5", t: "s2", q: "Por que a existência de um índice não garante consultas rápidas?",
    r: "<p>Porque o índice pode ter <b>baixa seletividade</b> (poucos valores distintos, ex.: sexo, ativo/inativo), estar <b>fragmentado</b>, ou a consulta pode exigir <b>muitas leituras aleatórias</b> na tabela depois de consultar o índice. Além disso, locks e falta de memória para cache também deixam a consulta lenta.</p>",
    k: ["Baixa seletividade", "Fragmentação", "Muitas leituras aleatórias depois do índice"] },
  { f: "Semana 2 – Revisão 6", t: "s2", q: "Sob alta carga, o tempo de resposta salta de 1 s para 30 s, enquanto a vazão deixa de crescer. Explique com tempo de fila, tempo de serviço e ponto de saturação.",
    r: "<p>R = tempo de fila + tempo de serviço. Até o <b>ponto de saturação</b>, a vazão cresce com a carga e a fila é pequena. Ao atingir a capacidade máxima, a vazão chega ao <b>teto</b>: chegadas extras não são processadas mais rápido, só entram na <b>fila</b>. O tempo de serviço continua parecido, mas o tempo de fila cresce muito — por isso R vai de 1 s para 30 s com a vazão estagnada.</p>",
    k: ["R = fila + serviço", "Vazão atinge o teto na saturação", "Excedente vira fila", "Crescimento do R vem da espera"] },

  // ---------- Semana 3 – perguntas de revisão ----------
  { f: "Semana 3 – Revisão 1", t: "s3", q: "Processador A: 4,5 GHz, IPC 1,1. Processador B: 3,6 GHz, IPC 1,6. Calcule a taxa teórica de instruções por segundo e indique qual processa mais.",
    r: "<p>Taxa = IPC × frequência.</p><p>A = 1,1 × 4,5 G = <b>4,95 bilhões de instruções/s</b>.<br>B = 1,6 × 3,6 G = <b>5,76 bilhões de instruções/s</b>.</p><p><b>B processa mais</b>, mesmo com menor clock, porque faz mais trabalho por ciclo.</p>",
    k: ["Usa IPC × frequência", "A = 4,95 G instr/s", "B = 5,76 G instr/s", "Conclui que B processa mais"] },
  { f: "Semana 3 – Revisão 2", t: "s3", q: "Por que a fórmula simplificada do tempo de CPU não representa todo o tempo de resposta de uma aplicação?",
    r: "<p>Porque ela só calcula o tempo de <b>processamento</b> das instruções. A aplicação também espera <b>memória</b> (cache misses), <b>armazenamento</b>, <b>rede</b>, o <b>sistema operacional</b> e filas/locks. O usuário percebe a soma de tudo.</p>",
    k: ["Fórmula = só processamento", "Esperas de memória/disco/rede/SO", "Usuário percebe o total"] },
  { f: "Semana 3 – Revisão 3", t: "s3", q: "Explique a diferença entre localidade temporal e espacial, com exemplo de cada.",
    r: "<p><b>Temporal</b>: um dado usado recentemente tende a ser usado de novo em breve. Ex.: variável contadora consultada em cada iteração de um laço.</p><p><b>Espacial</b>: após acessar um endereço, endereços vizinhos tendem a ser acessados. Ex.: percorrer um vetor em ordem. A cache explora as duas para aumentar a taxa de acertos.</p>",
    k: ["Temporal: reuso do mesmo dado", "Exemplo temporal (laço)", "Espacial: endereços vizinhos", "Exemplo espacial (vetor)"] },
  { f: "Semana 3 – Revisão 4", t: "s3", q: "Por que instalar mais RAM nem sempre torna o computador mais rápido?",
    r: "<p>RAM extra só ajuda quando a memória atual é <b>insuficiente</b> (há paginação/swap). Se os programas e dados já cabem com folga, a RAM a mais fica ociosa e não acelera a tarefa — o gargalo pode estar na CPU, no disco ou na rede.</p>",
    k: ["Ajuda só se falta memória (swap)", "Com folga, não acelera", "Gargalo pode estar em outro recurso"] },
  { f: "Semana 3 – Revisão 5", t: "s3", q: "Quais partes do acesso a um HDD são mecânicas? Por que isso prejudica os acessos aleatórios?",
    r: "<p>Tempo de acesso = <b>busca (seek)</b> + <b>latência rotacional</b> + transferência. As duas primeiras são <b>mecânicas</b>: mover o cabeçote e esperar o setor passar. Em acesso aleatório, cada pedido está em um lugar diferente, então se paga seek + rotação <b>a cada acesso</b> — por isso o HDD fica muito lento (caso Alfa: 125 IOPS).</p>",
    k: ["Seek e latência rotacional são mecânicas", "Cada acesso aleatório paga esse custo", "Poucos IOPS"] },
  { f: "Semana 3 – Revisão 6", t: "s3", q: "Por que um benchmark de CPU não basta para prever o desempenho de uma aplicação que depende muito de leitura e gravação?",
    r: "<p>Porque o benchmark vale para <b>a carga testada</b>. Um teste de CPU mede processamento; uma aplicação I/O-bound é limitada pelo armazenamento (latência, IOPS, acesso aleatório). Seria preciso um benchmark/teste com carga representativa de E/S.</p>",
    k: ["Benchmark vale para a carga testada", "Aplicação I/O-bound limitada pelo disco", "Usar carga representativa"] },
  { f: "Semana 3 – Revisão 7", t: "s3", q: "No caso Alfa x Beta, por que Beta pode ser melhor em alguns testes, mas ainda não atender a um setor que precisa de mais RAM ou disco?",
    r: "<p>Beta venceu na simulação paralela (105 s × 180 s, 8 núcleos) e nas consultas aleatórias (1,9 s × 38,2 s, NVMe). Mas tem só <b>16 GB de RAM</b> e <b>512 GB</b> de SSD. Se a simulação precisar de 20 GB, haverá swap e o desempenho cai; se a base tiver 800 GB, não cabe. Desempenho medido precisa ser comparado com a <b>capacidade necessária</b> — não existe vencedora universal.</p>",
    k: ["Beta melhor em paralelismo e aleatório", "16 GB < 20 GB → swap", "512 GB < 800 GB", "Capacidade também é requisito"] },

  // ---------- Semana 4 – perguntas de revisão ----------
  { f: "Semana 4 – Revisão 1", t: "s4", q: "Diferencie largura de banda nominal e throughput. Por que um link de 1 Gbps não garantiu aulas estáveis na Universidade XYZ?",
    r: "<p><b>Nominal</b>: capacidade anunciada do link. <b>Throughput</b>: dados úteis que realmente chegam (menor por overhead de protocolo, compartilhamento e interferências — no Wi-Fi, ~31–42% do nominal).</p><p>O link de 1 Gbps não garantiu estabilidade porque aulas ao vivo dependem de <b>latência, jitter e perda</b>, e o problema pode estar no Wi-Fi, na rede interna, em filas (bufferbloat) ou em equipamentos intermediários — não na capacidade do link externo.</p>",
    k: ["Nominal = anunciada", "Throughput = real/útil", "Multimídia depende de latência, jitter e perda", "Problema pode ser interno (Wi-Fi, filas)"] },
  { f: "Semana 4 – Revisão 2", t: "s4", q: "Explique a diferença entre latência e jitter. Como cada um pode prejudicar uma videoconferência?",
    r: "<p><b>Latência</b>: tempo para o pacote chegar. Alta latência causa atraso na conversa — as pessoas falam ao mesmo tempo, a interação fica artificial.</p><p><b>Jitter</b>: variação desse atraso. Jitter alto faz os pacotes chegarem irregulares; o buffer de jitter esvazia (cortes, travamentos) ou descarta pacotes tardios (áudio picotado).</p>",
    k: ["Latência = atraso", "Efeito: conversa atrasada/sobreposta", "Jitter = variação do atraso", "Efeito: cortes/travamentos"] },
  { f: "Semana 4 – Revisão 3", t: "s4", q: "O que é perda de pacotes e quais são duas possíveis causas?",
    r: "<p>Perda é quando um pacote <b>não chega ao destino</b>. Causas: <b>problemas físicos</b> (interferência, sinal fraco, falha no meio) e <b>filas cheias</b> em equipamentos intermediários que descartam novos pacotes (estouro de buffer por congestionamento).</p>",
    k: ["Pacote não chega", "Causa física (interferência/sinal)", "Fila cheia / congestionamento"] },
  { f: "Semana 4 – Revisão 4", t: "s4", q: "O que é um buffer de jitter e como ele ajuda na reprodução de áudio e vídeo?",
    r: "<p>É uma pequena área de memória no receptor que <b>guarda temporariamente</b> os pacotes recebidos para reproduzi-los em <b>intervalos regulares</b>, absorvendo a variação de chegada. Se esvazia (pacote atrasou demais), há cortes; se enche ou o pacote chega depois da hora, ele é descartado.</p>",
    k: ["Armazena temporariamente", "Reproduz em ritmo regular", "Vazio → cortes; tardio → descarte"] },
  { f: "Semana 4 – Revisão 5", t: "s4", q: "Qual a diferença básica entre TCP e UDP? Por que a priorização de tráfego (QoS) pode ajudar, mas não resolve toda limitação da rede?",
    r: "<p>TCP: entrega confiável, com retransmissão. UDP: sem garantia nem retransmissão, menor atraso — bom para tempo real.</p><p>QoS classifica e prioriza voz/vídeo sobre tráfego que pode esperar, reduzindo atraso/perda desses fluxos. Mas <b>não aumenta a capacidade física</b> do link nem elimina o atraso da distância; se a demanda total superar a capacidade, ainda haverá atrasos e perdas.</p>",
    k: ["TCP confiável/retransmite", "UDP sem garantia, menor atraso", "QoS prioriza tráfego sensível", "QoS não cria capacidade"] },

  // ---------- Semana 5 – perguntas de revisão ----------
  { f: "Semana 5 – Revisão 4", t: "s5", q: "Por que a avaliação de desempenho é importante no momento de escolher ou modernizar uma infraestrutura?",
    r: "<p>Porque transforma medições e requisitos em <b>informação para decisão</b>: permite verificar se a solução atende aos requisitos (vazão, tempo de resposta, disponibilidade), comparar alternativas de forma justa, estimar riscos, planejar crescimento e <b>justificar investimentos</b> com evidências, evitando comprar o mais caro ou o mais barato sem necessidade.</p>",
    k: ["Apoia decisão com evidências", "Verifica requisitos", "Compara alternativas / riscos", "Justifica investimento"] },
  { f: "Semana 5 – Revisão 5", t: "s5", q: "O que significa comparar duas tecnologias em condições equivalentes? Dê um exemplo de condição que deve ser mantida.",
    r: "<p>Significa aplicar o <b>ceteris paribus</b>: manter constantes todas as condições, exceto a tecnologia avaliada, para que a diferença observada seja atribuída a ela. Exemplo: usar a <b>mesma base de dados</b> e o <b>mesmo número de usuários simultâneos</b> nos dois servidores (também mesmas operações e rede).</p>",
    k: ["Ceteris paribus", "Só a tecnologia muda", "Exemplo: mesma base/mesma carga"] },
  { f: "Semana 5 – Revisão 6", t: "s5", q: "Qual é a diferença entre tempo de resposta e vazão?",
    r: "<p><b>Tempo de resposta</b>: quanto tempo uma solicitação leva para ser concluída (ex.: 0,40 s). <b>Vazão</b>: quantas solicitações são concluídas por unidade de tempo (ex.: 280 req/s).</p>",
    k: ["Tempo por solicitação", "Quantidade por unidade de tempo"] },
  { f: "Semana 5 – Revisão 7", t: "s5", q: "O que significa disponibilidade de 99,8%? Por que é importante para um e-commerce?",
    r: "<p>O serviço fica acessível 99,8% do tempo — cerca de <b>17,5 h fora do ar por ano</b>. Para um e-commerce, cada hora parada é venda perdida (na Fictícia Varejo, ~R$ 35.000/h em períodos críticos), além de dano à imagem e perda de clientes.</p>",
    k: ["≈17,5 h/ano fora do ar", "Hora parada = vendas perdidas", "R$ 35 mil/h no caso"] },
  { f: "Semana 5 – Revisão 8", t: "s5", q: "Explique a diferença entre escalabilidade vertical e horizontal.",
    r: "<p><b>Vertical (scale-up)</b>: aumentar recursos de uma mesma máquina (mais RAM, CPU melhor); tem limite físico e custo alto. <b>Horizontal (scale-out)</b>: acrescentar máquinas/instâncias trabalhando em conjunto; comum em nuvem e sistemas distribuídos. Mais servidores não resolvem gargalo em recurso compartilhado (ex.: BD).</p>",
    k: ["Vertical = mesma máquina mais forte", "Horizontal = mais máquinas", "Limitações de cada"] },
  { f: "Semana 5 – Revisão 9", t: "s5", q: "Qual é a diferença entre CapEx e OpEx? Por que os dois devem ser considerados no TCO?",
    r: "<p><b>CapEx</b>: investimento inicial em ativos (servidores, equipamentos de rede, licenças permanentes, estrutura). <b>OpEx</b>: gastos recorrentes (energia, refrigeração, links, suporte, equipe, mensalidades de nuvem).</p><p>Uma solução barata na compra pode ficar cara ao longo do tempo (energia, manutenção, especialistas). O TCO = CapEx + OpEx em um <b>período comum</b> (ex.: 3 anos) permite comparar de verdade.</p>",
    k: ["CapEx = investimento inicial", "OpEx = recorrente", "Barato na compra pode ser caro no tempo", "Mesmo período de comparação"] },
  { f: "Semana 5 – Revisão 10", t: "s5", q: "O que é manutenibilidade e como ela pode afetar uma equipe pequena?",
    r: "<p>É a facilidade de <b>manter, corrigir, atualizar e recuperar</b> a solução, e o esforço que isso exige. Numa equipe pequena, uma infraestrutura com troca frequente de peças, atualizações manuais e administração constante consome o tempo de todos, aumenta o risco de erro e o MTTR. Serviços gerenciados transferem parte disso ao fornecedor (mas ainda exigem gestão).</p>",
    k: ["Facilidade de manter/corrigir/atualizar", "Consome tempo da equipe pequena", "Serviço gerenciado alivia, mas exige gestão"] },
  { f: "Semana 5 – Revisão 11", t: "s5", q: "Como funciona uma matriz de decisão ponderada? O que representam os pesos?",
    r: "<p>Para cada alternativa, atribui-se uma <b>nota de 1 a 5</b> (justificada com dados) em cada critério; multiplica-se pela <b>peso</b> do critério e soma-se: Pontuação = D×0,30 + Disp×0,20 + Esc×0,20 + Custo×0,20 + Manut×0,10. Os <b>pesos</b> representam a <b>importância relativa</b> de cada critério para a organização. Antes, verificar requisitos obrigatórios; depois, fazer análise de sensibilidade.</p>",
    k: ["Notas 1–5 justificadas", "Nota × peso, soma", "Pesos = importância relativa", "Requisitos obrigatórios antes; sensibilidade depois"] },
  { f: "Semana 5 – Revisão 12", t: "s5", q: "Por que uma única execução de um teste pode levar a uma conclusão equivocada?",
    r: "<p>Porque os resultados <b>variam</b> entre execuções (estado do sistema, cache, outros processos, rede). Uma execução pode ser atípica. É preciso repetir, calcular média e variabilidade e intervalos de confiança (90%/95%). A média também pode esconder picos (200 ms com picos de 1.200 ms).</p>",
    k: ["Resultados variam", "Execução pode ser atípica", "Repetir; média, variabilidade, IC"] },
  { f: "Semana 5 – Revisão 13", t: "s5", q: "Por que a Alternativa A foi descartada antes do cálculo da pontuação? Em quais condições a B poderia ser preferível à C?",
    r: "<p>A <b>não atende requisitos obrigatórios</b>: 65 req/s (< 250) com 4,2 s (> 1 s) e 98,5% (< 99,8%). Preço baixo não compensa.</p><p>B poderia ser preferível se a empresa tiver <b>orçamento mais limitado</b>, <b>infraestrutura local já disponível</b>, <b>equipe especializada</b> ou restrições de conectividade/contratação de nuvem — desde que B continue atendendo aos requisitos (ela atende no limite: 280 req/s, 0,40 s, 99,8%).</p>",
    k: ["A falha em desempenho e disponibilidade", "Requisitos antes da pontuação", "B: orçamento/infra local/equipe/restrição de nuvem", "Desde que atenda aos requisitos"] },

  // ---------- Semana 6 – perguntas de revisão ----------
  { f: "Semana 6 – Revisão 7", t: "s6", q: "Qual a diferença entre medir um sistema, representá-lo por um modelo matemático e simulá-lo?",
    r: "<p><b>Medir</b>: observar e registrar o sistema real ou protótipo — mostra a realidade, mas só do cenário medido. <b>Modelo matemático (analítico)</b>: relações simplificadas (ex.: filas, Little) — estimativas rápidas, dependem de hipóteses. <b>Simular</b>: modelo executável que imita o funcionamento — testa cenários difíceis/caros, mas precisa ser construído e validado.</p>",
    k: ["Medição = real, cenário medido", "Analítico = matemática, hipóteses", "Simulação = modelo executável, cenários", "Limitação de cada"] },
  { f: "Semana 6 – Revisão 8", t: "s6", q: "Por que o tempo de resposta pode crescer rapidamente quando um recurso se aproxima da saturação?",
    r: "<p>Porque, perto da capacidade, sobra pouca folga para absorver variações e picos; a fila cresce e R = espera + serviço explode de forma <b>não linear</b>. No M/M/1 com S = 2 ms: 80% → 10 ms, 90% → 20 ms, 95% → 40 ms, 98% → 100 ms (R = S/(1−U)).</p>",
    k: ["Pouca folga para picos", "Fila cresce", "Não linear", "Exemplo M/M/1"] },
  { f: "Semana 6 – Revisão 9", t: "s6", q: "O que a Lei de Little relaciona? Explique com suas palavras.",
    r: "<p>Relaciona a <b>quantidade média de requisições no sistema (N)</b>, a <b>vazão (X)</b> e o <b>tempo médio de resposta (R)</b>: N = X × R. Quanto mais tempo cada requisição fica e mais requisições passam por segundo, mais requisições estão \"dentro\" do sistema ao mesmo tempo. Ex.: 20 req/s × 0,5 s = 10.</p>",
    k: ["N = X × R", "N = requisições no sistema", "Exemplo numérico"] },
  { f: "Semana 6 – Revisão 10", t: "s6", q: "Qual a diferença entre simulação dirigida por tempo e por eventos?",
    r: "<p><b>Por tempo</b>: o relógio avança em <b>intervalos fixos</b> (ex.: a cada 10 ms), mesmo que nada aconteça. <b>Por eventos</b>: o relógio <b>salta para o próximo evento</b> relevante (chegada, fim de atendimento), ignorando períodos sem atividade — muito usada em filas e redes.</p>",
    k: ["Tempo: passos fixos", "Eventos: salta para o próximo evento", "Eventos ignora ociosidade"] },
  { f: "Semana 6 – Revisão 11", t: "s6", q: "Por que uma simulação precisa ser repetida e comparada com dados reais?",
    r: "<p>Repetida porque tem elementos aleatórios: uma execução pode ser atípica (usar e variar <b>seeds</b>, descartar <b>warm-up</b>). Comparada com dados reais porque a simulação só mostra o que acontece <b>dentro das regras programadas</b>; se dados ou premissas estiverem errados, o resultado não é confiável. Ela não transforma hipótese em fato.</p>",
    k: ["Aleatoriedade → repetir", "Seeds e warm-up", "Validar com dados reais", "Não transforma hipótese em fato"] },
  { f: "Semana 6 – Revisão 12", t: "s6", q: "No caso da Fictícia Varejo, por que o banco de dados merece atenção especial na projeção de 500 req/s?",
    r: "<p>Pela Lei da Utilização (U = X × S), com 1,8 ms por requisição, o BD vai de 45% (250 req/s) para <b>90%</b> (500 req/s) — o maior de todos. A 90% sobra pouca folga e o tempo de resposta cresce muito (M/M/1: R = 10× S). Além disso, o BD é um recurso <b>compartilhado</b>: aumentar servidores web não resolve. A projeção de &gt; 1,8 s é um alerta a confirmar com testes.</p>",
    k: ["U = X × S → 90%", "Maior utilização projetada", "Pouca folga; R cresce", "Recurso compartilhado; web extra não resolve"] },
];
